            ]
            aliasBy    = "{{metric.label.instance_name}} → {{metric.label.replica_addr}}"
            editorMode = "visual"
          }
        })
      }

      data {
        ref_id         = "C"
        datasource_uid = "__expr__"
        relative_time_range {
          from = 0
          to   = 0
        }
        model = jsonencode({
          type       = "threshold"
          expression = "A"
          refId      = "C"
          conditions = [{
            evaluator = { params = [30], type = "gt" }
            operator  = { type = "and" }
            query     = { params = ["C"] }
