# ── /v1/chat/completions ─────────────────────────────────────────────
# Passthrough to Vertex's OpenAI-compatible endpoint. Google's endpoint
# already sanitizes tool schemas (accepts OpenAPI fields like `deprecated`
# and `x-*` extensions without complaint), so we don't strip anything.
# We only rewrite the model name (gemini-2.5-flash → google/gemini-2.5-flash)
# because Vertex's endpoint rejects unqualified names.

@app.post("/v1/chat/completions")
def chat_completions():
    auth_err = _check_bearer()
    if auth_err is not None:
        return auth_err
    body = request.get_json(silent=True) or {}
    model = body.get("model", "")
    if model and "/" not in model and CHAT_MODEL_PREFIX:
        body["model"] = CHAT_MODEL_PREFIX + model

    stream = bool(body.get("stream"))
    url = f"{VERTEX_OPENAI_BASE}/chat/completions"

    # Retry once on 401 (cache may have gone stale between checks).
    for attempt in (1, 2):
        token = get_token(force_refresh=(attempt == 2))
        t0 = time.time()
        upstream = requests.post(
            url,
            headers={
                "Authorization": f"Bearer {token}",
                "Content-Type": "application/json",
            },
            json=body,
            stream=stream,
            timeout=REQUEST_TIMEOUT,
        )
        if upstream.status_code == 401 and attempt == 1:
            _logj("warning", "chat_401_retrying")
            upstream.close()
            continue
        break

    dt_ms = int((time.time() - t0) * 1000)
    _logj(
        "info",
        "chat_call",
        status=upstream.status_code,
        model=body.get("model"),
        stream=stream,
        latency_ms=dt_ms,
    )

    # Non-streaming: return the full body at once.
    if not stream:
        return Response(
            upstream.content,
            status=upstream.status_code,
            content_type=upstream.headers.get("content-type", "application/json"),
        )

    # Streaming: forward chunks verbatim (SSE for OpenAI-style streams).
    def generate():
        try:
            for chunk in upstream.iter_content(chunk_size=None):
                if chunk:
                    yield chunk
        finally:
            upstream.close()

    return Response(
        stream_with_context(generate()),
        status=upstream.status_code,
        content_type=upstream.headers.get("content-type", "text/event-stream"),
    )


# ── /v1/embeddings ───────────────────────────────────────────────────
# Translate OpenAI → Vertex :predict. The Vertex OpenAI-compat endpoint
# (/v1beta1/.../endpoints/openapi/embeddings) returns HTTP 500 for this
# region/project, so we cannot passthrough here.

@app.post("/v1/embeddings")
def embeddings():

