import requests
from flask import Flask, Response, jsonify, request, stream_with_context

# ── OTLP tracing (opcional, a Phoenix) ────────────────────────────────
# Gated por OTEL_ENABLED=true; si no, no importa siquiera las deps.
# Semantic conventions: OpenInference (span.kind=LLM|EMBEDDING).
_tracer = None
if os.getenv("OTEL_ENABLED", "false").lower() == "true":
    try:
        from contextlib import contextmanager, nullcontext  # noqa: F401

        from opentelemetry import trace as _otel_trace
        from opentelemetry.exporter.otlp.proto.grpc.trace_exporter import (
            OTLPSpanExporter,
        )
        from opentelemetry.sdk.resources import Resource
        from opentelemetry.sdk.trace import TracerProvider
        from opentelemetry.sdk.trace.export import BatchSpanProcessor

        _otel_resource = Resource.create(
            {
                "service.name": os.getenv("OTEL_SERVICE_NAME", "vertex-adapter"),
                "openinference.project.name": os.getenv("PHOENIX_PROJECT_NAME", "openfang"),
            }
        )
        _otel_provider = TracerProvider(resource=_otel_resource)
        _otel_provider.add_span_processor(
            BatchSpanProcessor(
                OTLPSpanExporter(
                    endpoint=os.getenv("OTEL_EXPORTER_OTLP_ENDPOINT", "http://phoenix:4317"),
                    insecure=True,
                ),
                max_queue_size=512,
                max_export_batch_size=128,
                schedule_delay_millis=5000,
            )
        )
        _otel_trace.set_tracer_provider(_otel_provider)
        _tracer = _otel_trace.get_tracer("vertex-adapter")
    except Exception:  # noqa: BLE001
        _tracer = None


def _trace_span(name, kind):
    """Return an active span context manager, or a nullcontext if OTEL disabled."""
    if _tracer is None:
        from contextlib import nullcontext
        return nullcontext(None)
    cm = _tracer.start_as_current_span(name)
    return cm


def _record_llm_request(span, body):
    if span is None:
        return
    span.set_attribute("openinference.span.kind", "LLM")
    span.set_attribute("llm.provider", "google")
    span.set_attribute("llm.system", "vertex_ai")
    span.set_attribute("llm.model_name", str(body.get("model", ""))[:200])
    msgs = body.get("messages", [])
    span.set_attribute("llm.input_messages.count", len(msgs))
    # Capturar solo el último user message (ahorra tokens en Phoenix; prompt
    # completo disponible en Cloud Logging si hace falta).
    for msg in reversed(msgs):
        if msg.get("role") == "user":
            content = msg.get("content", "")
            if not isinstance(content, str):
                content = json.dumps(content)[:2000]
            span.set_attribute("llm.input_messages.last_user", content[:2000])
            break
    tools = body.get("tools", [])
    if tools:
        span.set_attribute("llm.tools_count", len(tools))


def _record_embedding_request(span, body):
    if span is None:
        return
    span.set_attribute("openinference.span.kind", "EMBEDDING")
    span.set_attribute("llm.provider", "google")
    span.set_attribute("llm.system", "vertex_ai")
    span.set_attribute("embedding.model_name", str(body.get("model", ""))[:200])
    inp = body.get("input", "")
    if isinstance(inp, list):
        span.set_attribute("embedding.input_count", len(inp))
    else:
        span.set_attribute("embedding.input_count", 1)


def _record_llm_response(span, response_json, status_code, latency_ms, streaming=False):
    if span is None:
        return
    span.set_attribute("http.status_code", int(status_code))
    span.set_attribute("latency.ms", int(latency_ms))
    span.set_attribute("llm.is_streaming", bool(streaming))
    if status_code >= 400:
        from opentelemetry.trace import Status, StatusCode  # type: ignore
        span.set_status(Status(StatusCode.ERROR))
    if not response_json:
        return
    usage = response_json.get("usage") or {}
    if usage:
        span.set_attribute("llm.token_count.prompt", int(usage.get("prompt_tokens", 0) or 0))
        span.set_attribute("llm.token_count.completion", int(usage.get("completion_tokens", 0) or 0))
        span.set_attribute("llm.token_count.total", int(usage.get("total_tokens", 0) or 0))
    choices = response_json.get("choices") or []
    if choices:
        first = choices[0].get("message") or {}
        tc_count = len(first.get("tool_calls") or [])
        span.set_attribute("llm.output_messages.tool_calls_count", tc_count)
        span.set_attribute("llm.output_messages.finish_reason", str(choices[0].get("finish_reason", "")))

